import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        long[] pages = new long[n];
        for (int i = 0; i < n; i++) pages[i] = r.nextLong();
        // Key orders by threshold ascending, then pages descending.
        final long cap = 1L << 30;
        long[] key = new long[n];
        for (int i = 0; i < n; i++) key[i] = (r.nextLong() << 31) | (cap - pages[i]);
        Arrays.sort(key);
        long ans = 0;
        for (int i = 0; i < n;) {
            long t = key[i] >> 31;
            int j = i;
            while (j < n && (key[j] >> 31) == t) {
                if (j - i < t) ans += cap - (key[j] & ((1L << 31) - 1));
                j++;
            }
            i = j;
        }
        System.out.println(ans);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

