import (
	"bufio"
	"cmp"
	"fmt"
	"os"
	"slices"
)

func main() {
	n := readInt()
	type item struct{ t, p int }
	items := make([]item, n)
	for i := range items {
		items[i].p = readInt()
	}
	for i := range items {
		items[i].t = readInt()
	}
	// Threshold ascending, pages descending; take the first t of each group.
	slices.SortFunc(items, func(a, b item) int {
		if a.t != b.t {
			return cmp.Compare(a.t, b.t)
		}
		return cmp.Compare(b.p, a.p)
	})
	ans := 0
	for i := 0; i < n; {
		j := i
		for j < n && items[j].t == items[i].t {
			if j-i < items[i].t {
				ans += items[j].p
			}
			j++
		}
		i = j
	}
	fmt.Println(ans)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
